$src = [System.Drawing.Bitmap]::FromFile($In)
if ($DiffWith) {
    $other = [System.Drawing.Bitmap]::FromFile($DiffWith)
    $minX = 99999; $minY = 99999; $maxX = -1; $maxY = -1
    for ($yy = 0; $yy -lt $src.Height; $yy += 2) {
        for ($xx = 0; $xx -lt $src.Width; $xx += 2) {
            $a = $src.GetPixel($xx, $yy); $b = $other.GetPixel($xx, $yy)
            $d = [Math]::Abs($a.R - $b.R) + [Math]::Abs($a.G - $b.G) + [Math]::Abs($a.B - $b.B)
            if ($d -gt 90) { if ($xx -lt $minX) { $minX = $xx }; if ($yy -lt $minY) { $minY = $yy }; if ($xx -gt $maxX) { $maxX = $xx }; if ($yy -gt $maxY) { $maxY = $yy } }
        }
    }
    Write-Host "diff bbox: $minX,$minY - $maxX,$maxY"
    $other.Dispose()
}
if ($Out) {
    $dst = New-Object System.Drawing.Bitmap ([int]($W * $Scale)), ([int]($H * $Scale))
    $g = [System.Drawing.Graphics]::FromImage($dst)
    $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor
    $g.DrawImage($src, (New-Object System.Drawing.Rectangle 0, 0, $dst.Width, $dst.Height), (New-Object System.Drawing.Rectangle $X, $Y, $W, $H), [System.Drawing.GraphicsUnit]::Pixel)
    $dst.Save($Out, [System.Drawing.Imaging.ImageFormat]::Png)
    $g.Dispose(); $dst.Dispose()
}
$src.Dispose()

