param([string]$Tag = 'it')
$ErrorActionPreference = 'Continue'
$root = 'C:\GameJam'
$lock = Join-Path $root 'Glyphbound\Saved\machine.lock'
$s = $PSScriptRoot
if (Test-Path $lock) {
    $age = (Get-Date) - (Get-Item $lock).LastWriteTime
    if ($age.TotalMinutes -lt 45) { Write-Host "LOCKED: $(Get-Content $lock)"; exit 3 }
}
Set-Content -Path $lock -Value "shotgun-tuning chat | build + smoke shotgun | $([DateTime]::UtcNow.ToString('u'))" -Encoding ascii
try {
    powershell -NoProfile -File (Join-Path $root 'Tools\Jam\Build-Jam.ps1') | Select-Object -Last 8
    if ($LASTEXITCODE -ne 0) { Write-Host 'BUILD FAILED'; exit 1 }
    powershell -NoProfile -File (Join-Path $root 'Tools\Jam\Smoke-Jam.ps1') -Only shotgun -Offscreen | Select-Object -Last 45
    $d = Join-Path $root 'Glyphbound\Saved\Screenshots\Smoke'
    foreach ($n in '15a_shotgun_hip', '15b_shotgun_pump', '15d_shotgun_reload_shell') {
        $f = Join-Path $d "$n.png"
        if (Test-Path $f) {
            Copy-Item $f (Join-Path $s "${Tag}_$n.png") -Force
            powershell -NoProfile -File (Join-Path $s 'crop.ps1') -In $f -Out (Join-Path $s "${Tag}_${n}_crop.png") -X 560 -Y 300 -W 720 -H 420 -Scale 1.4
        }
    }
} finally {
    Remove-Item $lock -Force -ErrorAction SilentlyContinue
}

